   "url": "https://www.woshipm.com/operate/6466631.html",
   "summary": "很多开发者接了越来越多广告平台，收入却没有同步上涨，问题不在于广告源不够多，而在于所有用户都被送进同一条 Waterfall。文章以 Taku 的用户价值分组为例，把设备按历史广告表现划出价值区间、各走不同瀑布流，再用 A/B 测试检验效果。 假设你正在运营一款App。用户A经常使用产品，过去展示的广告价格也比较高；用户B偶尔打开，历史广告价值相对较低。 两个人虽然价值不同，发起广告请求时，却可能进入同一套Waterfall，也就是按照设定顺序，从高价广告源一路向下请求。 这就像让购买力不同的顾客，都从最高价商品开始逐一询问。对用户B来说，前面的高价广告源很可能连续请求失败，既浪费时间，也影响",
