   "title": "不写一个字，却可能是 AI 时代最重要的模型",
   "url": "https://www.woshipm.com/ai/6466421.html",
   "summary": "TypeSafe AI 发布的 Jev 不生成任何文字，只在几百毫秒内并行给出带概率值的结构化决策。创始人 Diogo Almeida 是 ChatGPT 的联合发明人之一、RLHF 的重要贡献者，他用两年时间回答一个问题：模型这么聪明，自动化为什么还难落地。 你有没有想过，AI 模型最大的问题从来不是不够聪明，而是不够可靠？我们已经用了好几年的 ChatGPT、Claude、Gemini，它们能写文章、写代码、解释任何概念，聪明得让人叹服。但如果你真的要把它们嵌进一个生产环境里，让它每秒钟做几百次决策，你会立刻撞上一堵墙：它们太飘了。同样一个问题问两次，答案可能不一样。让它返回结构化的 JS",
