   "summary": "37K Star 的 1Panel 开放了 AI 网关的独立部署能力，10 人及以下团队可以免费使用。网关能集中管理各家模型的原始密钥，给成员分配权限、按任务分配模型，也能看清每个人的调用用量，再据此调整配额。 之前介绍过一个开源项目，叫 1Panel。 它是一款 Linux 服务器管理工具。 可以通过网页控制台来搭建网站、安装应用、管理数据库、部署 AI 应用和做备份，减少手动输入命令的操作。 这次，1Panel开放了AI 网关的独立部署能力。 10 人及以下团队可以免费使用。 接入后，团队使用的不同模型可以放在一起管理。 给成员分配访问权限，给应用设置用量配额、调整模型调用，都可以在网关里",
