   "url": "https://www.woshipm.com/share/6466187.html",
   "summary": "看完《AI全球商业版图》里 34 家 AI 公司的案例后最大的感受：模型是入场券，真正决定一家公司能不能把技术变成生意的，是它站在产业链的什么位置、解决了什么问题。卖算力、卖模型、卖平台、卖消费品，赚钱难度完全不同。 看完《AI全球商业版图》这本书，学到了不少，过去我一直以为，AI竞争就是模型竞赛，比如谁参数更大、谁榜单更高、谁更接近AGI（通用人工智能），谁就更有机会赢。 但这本书把海外19家、国内15家，一共34家AI公司放在一起分析之后，我有了不一样的感觉：模型能力很重要，但模型能力并不直接等于商业能力。 模型是入场券，但真正决定一家AI公司能不能把技术变成生意的，是它站在产业链的什么位",
